//! Python source text: literals, docstrings and the generated-file header.

/// The first line of every generated file. `write` removes a stale file of
/// `_catalog/` only when it starts with this line.
pub const GENERATED_HEADER: &str = "# Generated by horsies-codegen from horsies-core. Do not edit.";

/// A Python string literal in single quotes.
pub fn string_literal(text: &str) -> String {
    let mut literal = String::with_capacity(text.len() + 2);
    literal.push('\'');
    for character in text.chars() {
        match character {
            '\\' => literal.push_str("\\\\"),
            '\'' => literal.push_str("\\'"),
            '\n' => literal.push_str("\\n"),
            other => literal.push(other),
        }
    }
    literal.push('\'');
    literal
}

/// A docstring at `indent`, or nothing when `doc` is empty. Backslashes and
/// double quotes are escaped, so no text can end the docstring early.
pub fn docstring(doc: &str, indent: &str) -> Option<String> {
    let trimmed = doc.trim();
    if trimmed.is_empty() {
        return None;
    }
    let escaped = trimmed.replace('\\', "\\\\").replace('"', "\\\"");
    let lines: Vec<&str> = escaped.lines().collect();
    match lines.as_slice() {
        [single] => Some(format!("{indent}\"\"\"{single}\"\"\"\n")),
        _ => {
            let mut text = format!("{indent}\"\"\"");
            for (position, line) in lines.iter().enumerate() {
                match (position, line.trim_end().is_empty()) {
                    (0, _) => text.push_str(line.trim_end()),
                    (_, true) => text.push('\n'),
                    (_, false) => {
                        text.push('\n');
                        text.push_str(indent);
                        text.push_str(line.trim_end());
                    }
                }
            }
            text.push('\n');
            text.push_str(indent);
            text.push_str("\"\"\"\n");
            Some(text)
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn a_literal_escapes_quotes_backslashes_and_newlines() {
        assert_eq!(string_literal("PENDING"), "'PENDING'");
        assert_eq!(string_literal("a'b\\c\nd"), "'a\\'b\\\\c\\nd'");
    }

    #[test]
    fn an_empty_doc_gives_no_docstring() {
        assert_eq!(docstring("  \n ", "    "), None);
    }

    #[test]
    fn a_one_line_doc_stays_on_one_line() {
        assert_eq!(
            docstring("Task status.", "    "),
            Some("    \"\"\"Task status.\"\"\"\n".to_owned())
        );
    }

    #[test]
    fn a_doc_of_several_lines_is_indented_and_escaped() {
        let rendered =
            docstring("First \"line\".\n\nThird \\ line.", "    ").expect("the doc is not empty");
        assert_eq!(
            rendered,
            "    \"\"\"First \\\"line\\\".\n\n    Third \\\\ line.\n    \"\"\"\n"
        );
    }
}
